import { Fragment, type ReactNode } from "react";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";

export interface KeyValueItem {
  k: ReactNode;
  v: ReactNode;
}
export interface KeyValueListProps {
  items?: KeyValueItem[];
  labelWidth?: number;
  mono?: boolean;
  loading?: boolean;
  className?: string;
}
const DEMO_ITEMS: KeyValueItem[] = [
  { k: "repo", v: "base-studio-code" },
  { k: "branch", v: "develop" },
  { k: "issues", v: 42 },
];
export function KeyValueList({ items = DEMO_ITEMS, labelWidth = 120, mono, loading, className }: KeyValueListProps) {
  if (!loading && items.length === 0) {
    return <div className={className} style={{ fontSize: 11, color: "var(--fg-dim)" }}>No data.</div>;
  }
  return (
    <div
      className={className}
      style={{
        display: "grid",
        gridTemplateColumns: `${labelWidth}px 1fr`,
        rowGap: 7,
        columnGap: 12,
        alignItems: "baseline",
      }}
    >
      {items.map((it, i) => (
        <Fragment key={i}>
          <span
            style={{
              fontFamily: "var(--mono)",
              fontSize: 10,
              textTransform: "uppercase",
              letterSpacing: ".05em",
              color: "var(--fg-muted)",
            }}
          >
            {it.k}
          </span>
          {loading ? (
            <Skeleton h={11} w="60%" radius={4} />
          ) : (
            <span style={{ fontSize: 12, color: "var(--fg)", ...(mono ? { fontFamily: "var(--mono)" } : {}) }}>
              {it.v}
            </span>
          )}
        </Fragment>
      ))}
    </div>
  );
}

